def main():
    ids = [p["case_id"] for p in PREDS]
    assert len(PREDS) == 20, f"count {len(PREDS)} != 20"
    assert set(ids) == set(BATCH), f"id set mismatch: {sorted(set(ids) ^ set(BATCH))}"
    assert len(set(ids)) == 20, "duplicate ids"
    for p in PREDS:
        for k in ("case_id", "prediction_text", "basis", "confidence", "trigger"):
            assert k in p, (p.get("case_id"), k)
        assert 0.0 <= float(p["confidence"]) <= 1.0
        t = p["trigger"]
        for b in ("changed_main", "reserve_used", "disputed"):
            assert isinstance(t[b], bool), (p["case_id"], b)
        assert isinstance(t["reason"], str) and t["reason"]
        assert "第八节功量核标目" in p["basis"], p["case_id"]
        assert "主线认定" in p["basis"], p["case_id"]
    os.makedirs(OUT, exist_ok=True)
    for p in PREDS:
        with open(os.path.join(OUT, p["case_id"] + ".json"), "w", encoding="utf-8") as f:
            json.dump(p, f, ensure_ascii=False, indent=1)
    cm = sum(1 for p in PREDS if p["trigger"]["changed_main"])
    ru = sum(1 for p in PREDS if p["trigger"]["reserve_used"])
    di = sum(1 for p in PREDS if p["trigger"]["disputed"])
    print(f"WROTE {len(PREDS)} files to {OUT}")
    print(f"trigger counts: changed_main={cm} reserve_used={ru} disputed={di}")

if __name__ == "__main__":
    main()
